'use strict';

// GHSA-vfj7-8cjw-p6xm: check depth before any recursive brace AST walker.
// Parent/prev links are intentionally excluded; nodes is the tree edge.
module.exports = ast => {
  const pending = [{ node: ast, depth: 0 }];
  const active = new WeakSet();
  while (pending.length) {
    const { node, depth, leave } = pending.pop();
    if (!node || typeof node !== 'object') continue;
    if (leave) { active.delete(node); continue; }
    if (depth > 256) throw new SyntaxError('Brace pattern exceeds maximum nesting depth (256)');
    if (active.has(node)) throw new SyntaxError('Cyclic brace AST');
    active.add(node);
    pending.push({ node, leave: true });
    if (Array.isArray(node.nodes)) {
      for (let i = node.nodes.length - 1; i >= 0; i--) pending.push({ node: node.nodes[i], depth: depth + 1 });
    }
  }
};

